def hidden_rule_fn(state):
    n = len(state)
    next_state = [[0]*n for _ in range(n)]

    for r in range(n):
        for c in range(n):
            current = state[r][c]
            # Compute diagonal-tetrad neighbors with toroidal wrap
            ne = state[(r-1)%n][(c+1)%n]
            nw = state[(r-1)%n][(c-1)%n]
            se = state[(r+1)%n][(c+1)%n]
            sw = state[(r+1)%n][(c-1)%n]

            d_z = sum(1 for v in [ne, nw, se, sw] if v == 0)
            d_p = sum(1 for v in [ne, nw, se, sw] if v == 1)
            d_q = sum(1 for v in [ne, nw, se, sw] if v == 2)

            if d_p > 0:
                if d_q >= d_z:
                    next_state[r][c] = current
                else:
                    next_state[r][c] = (3 - current) % 3
            else:
                if d_z == d_q:
                    next_state[r][c] = (3 - current) % 3
                elif d_z > d_q:
                    next_state[r][c] = current
                else:
                    next_state[r][c] = (2 - current) % 3

    return next_state
